function compareRecordsByIdentity(
  left: Readonly<Record<string, JsonValue>>,
  right: Readonly<Record<string, JsonValue>>,
  identityKeys: readonly string[],
): number {
  for (const key of identityKeys) {
    const compared = compareUnicodeCodeUnits(
      left[key] as string,
      right[key] as string,
    );
    if (compared !== 0) return compared;
  }
  return compareUnicodeCodeUnits(canonicalJson(left), canonicalJson(right));
}

function canonicalizeStringInventory(
  carrier: MutableJsonRecord,
  field: string,
): void {
  const values = carrier[field];
  if (
    Array.isArray(values) &&
    values.every((value) => typeof value === "string")
  ) {
    carrier[field] = [...values].sort(compareUnicodeCodeUnits);
  }
}

function canonicalizeRecordInventory(
  carrier: MutableJsonRecord,
  field: string,
  identityKeys: readonly string[],
  canonicalizeEntry?: (entry: MutableJsonRecord) => void,
): void {
  const values = carrier[field];
  if (!Array.isArray(values)) return;

  const entries = values.map((value: JsonValue) => {
    if (!isRecord(value)) return value;
    const entry = mutable(value);
    canonicalizeEntry?.(entry);
    return entry;
  });
  if (
    entries.every(
      // A record entry is the mutable copy made above.
      (entry): entry is MutableJsonRecord =>
        isRecord(entry) &&
        identityKeys.every((key) => typeof entry[key] === "string"),
    )
  ) {
    entries.sort((left, right) =>
      compareRecordsByIdentity(left, right, identityKeys)
    );
  }
  carrier[field] = entries;
}

export function canonicalizeAuthoredGtlCarrier(
  value: JsonValue,
  subjectKind: CanonicalAuthoredGtlSubjectKind,
): unknown {
  // JSON.parse yields only JSON values: the parse of canonical text is in the domain.
  const cloned: JsonValue = JSON.parse(canonicalJson(value));
  if (!isRecord(cloned)) return deepFreeze(cloned);
  const carrier = mutable(cloned);
  switch (subjectKind) {
    case "module_publication":
      canonicalizeModulePublication(carrier);
      break;
    case "catalog_contribution":
      canonicalizeContribution(carrier);
      break;
    case "gtl_program":
      canonicalizeProgram(carrier);
      break;
    case "graph_function":
      canonicalizeGraphFunction(carrier);
      break;
  }
  return deepFreeze(carrier);
}

export function compareUnicodeCodeUnits(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

export function canonicalJson(value: JsonValue): string {
  const parts: string[] = [];
  writeCanonicalJson(value, (part) => { parts.push(part); });
  return parts.join("");
}

/** One byte-compatible traversal for collected text and incremental sinks. */
export function writeCanonicalJson(value: JsonValue, write: (part: string) => void): void {
  if (value === null || typeof value === "boolean" || typeof value === "string") {
    write(JSON.stringify(value));
    return;
  }

  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw new TypeError("canonical JSON does not admit non-finite numbers");
    }
    write(Object.is(value, -0) ? "0" : JSON.stringify(value));
    return;
  }

  if (Array.isArray(value)) {
    write("[");
    // map snapshots length and skips holes; join still emits their separators.
    const length = value.length;
    for (let index = 0; index < length; index += 1) {
      if (index !== 0) write(",");
      if (index in value) writeCanonicalJson(value[index]!, write);
    }
    write("]");
    return;
  }

  const entries = Object.entries(value).sort(([left], [right]) =>
    compareUnicodeCodeUnits(left, right)
  );
  write("{");
  for (let index = 0; index < entries.length; index += 1) {
    const [key, entry] = entries[index]!;
    if (index !== 0) write(",");
    write(JSON.stringify(key));
    write(":");
    writeCanonicalJson(entry, write);
  }
  write("}");
}

